import six
from abc import ABCMeta, abstractmethod


@six.add_metaclass(ABCMeta)
class Recorder(object):

    @abstractmethod
    def add(self, throughput_data):
        """pass"""

    def start(self):
        pass

    def stop(self):
        pass

    def reset(self):
        pass


class DictRecorder(Recorder):

    def __init__(self, output):
        self._data_dict = output

    def reset(self):
        self._data_dict.clear()

    def add(self, throughput_data):
        data = {'record_time': throughput_data.utc_time, 'throughput': throughput_data.current}
        if throughput_data.device_id in self._data_dict:
            self._data_dict[throughput_data.device_id].append(data)
        else:
            self._data_dict[throughput_data.device_id] = [data]


class CSVRecorder(Recorder):
    def __init__(self, output):
        self._file_path = output
        self._file_obj = None
        self._headers = ['cell_id', 'record_time', 'throughput']

    def add(self, throughput_data):
        values = [throughput_data.device_id, throughput_data.utc_time, throughput_data.current]
        self._write_line(values)

    def start(self):
        self._file_obj = open(self._file_path, 'w')
        self._write_line(self._headers)

    def stop(self):
        if self._file_obj:
            self._file_obj.close()
            self._file_obj = None

    def reset(self):
        self.stop()

    def _write_line(self, columns):
        self._file_obj.write("{}\r\n".format(str(columns).strip('[]')))


class DoNothingRecorder(Recorder):
    def add(self, cell_data):
        pass
